// C++ parity test suite comparing galaxia-rs against compiled Galaxia 0.7.2 objects.
// Fixtures generated by `tests/cpp/check_cpp_boundaries.cpp`.

use galaxia_rs::imf::Sampler;
use galaxia_rs::isochrone::{IsochroneDB, IsochroneFieldState};
use galaxia_rs::population::{create_population, StarParticle};
use galaxia_rs::rng::Philox;
use std::fs::File;
use std::path::PathBuf;

fn load_fixtures() -> serde_json::Value {
    let manifest_dir = PathBuf::from(env!("CARGO_MANIFEST_DIR"));
    let fixture_path = manifest_dir.join("tests/fixtures/cpp_boundaries.json");

    assert!(
        fixture_path.exists(),
        "fixture {} missing: regenerate it with scripts/run_cpp_parity_tests.sh (needs the original Galaxia 0.7.2 C++ build)",
        fixture_path.display()
    );

    let file = File::open(&fixture_path).expect("Open fixture file");
    serde_json::from_reader(file).expect("Parse JSON fixtures")
}

#[test]
fn test_cpp_parity_leaf_cutoff_witnesses() {
    let data_dir = galaxia_rs::require_data_dir!();
    let db = IsochroneDB::load(&data_dir).expect("Load IsochroneDB");
    let mut state = IsochroneFieldState::new(&db);
    let mut imf = Sampler::for_pop_id(7);
    let mut rng = Philox::from_stream(1, 0, 7, 0, 0, 0);

    // Leaf-specific cutoff scenario: max_v = 5.0
    db.set_isochrones1(
        &mut state, 11e9, 1e9, -0.78, 0.3, 5.0, 1000.0, 0, &mut imf, &mut rng,
    );

    let fixtures = load_fixtures();
    let witnesses = fixtures["leaf_cutoff_witnesses"]
        .as_array()
        .expect("leaf_cutoff_witnesses array");

    for w in witnesses {
        let name = w["name"].as_str().unwrap();
        let age = w["age"].as_f64().unwrap();
        let feh = w["feh"].as_f64().unwrap();
        let smass = w["smass"].as_f64().unwrap();
        let _exp_track_idx = w["track_idx"].as_i64().unwrap() as usize;
        let exp_accepted = w["accepted"].as_bool().unwrap();

        let mut star = StarParticle::default();
        star.age = age;
        star.feh = feh;
        star.smass = smass;

        db.interpolate_star(&mut star, &state);

        let accepted = star.abs_mags[0] < 1e5;
        assert_eq!(
            accepted, exp_accepted,
            "leaf-cutoff witness {}: accept/reject mismatch: expected {}, got {}",
            name, exp_accepted, accepted
        );

        if accepted {
            let exp_mags = w["mags"].as_array().unwrap();
            for m in 0..3 {
                let exp_m = exp_mags[m].as_f64().unwrap();
                let diff = (star.abs_mags[m] - exp_m).abs();
                assert!(
                    diff < 1e-4,
                    "leaf-cutoff witness {}: mag[{}] diff {} exceeds tolerance (expected {}, got {})",
                    name, m, diff, exp_m, star.abs_mags[m]
                );
            }
        }
    }
}

#[test]
fn test_cpp_parity_float_transition_witnesses() {
    let data_dir = galaxia_rs::require_data_dir!();
    let db = IsochroneDB::load(&data_dir).expect("Load IsochroneDB");
    let state = IsochroneFieldState::new(&db);

    let fixtures = load_fixtures();
    let witnesses = fixtures["float_transition_witnesses"]
        .as_array()
        .expect("float_transition_witnesses array");

    for w in witnesses {
        let name = w["name"].as_str().unwrap();
        let log_age = w["log_age"].as_f64().unwrap();
        let feh = w["feh"].as_f64().unwrap();
        let smass = w["smass"].as_f64().unwrap();

        // 1. Test interpolate_tgm (append1)
        let tgm_res = db.interpolate_tgm(log_age, feh, smass);
        let exp_tgm = w["tgm"].as_array().unwrap();
        let exp_l = exp_tgm[0].as_f64().unwrap();
        let exp_teff = exp_tgm[1].as_f64().unwrap();
        let exp_grav = exp_tgm[2].as_f64().unwrap();
        let exp_mact = exp_tgm[3].as_f64().unwrap();
        let exp_mtip = exp_tgm[4].as_f64().unwrap();

        assert!(
            (tgm_res.lum - exp_l).abs() < 1e-4,
            "float-quantization {}: TGM Lum diff",
            name
        );
        assert!(
            (tgm_res.teff - exp_teff).abs() < 1e-4,
            "float-quantization {}: TGM Teff diff",
            name
        );
        assert!(
            (tgm_res.grav - exp_grav).abs() < 1e-4,
            "float-quantization {}: TGM Grav diff",
            name
        );
        assert!(
            (tgm_res.mact - exp_mact).abs() < 1e-4,
            "float-quantization {}: TGM Mact diff",
            name
        );
        assert!(
            (tgm_res.mtip - exp_mtip).abs() < 1e-4,
            "float-quantization {}: TGM Mtip diff",
            name
        );

        // 2. Test interpolate_star
        let mut star = StarParticle::default();
        star.age = log_age;
        star.feh = feh;
        star.smass = smass;

        db.interpolate_star(&mut star, &state);

        let exp_mags = w["star_mags"].as_array().unwrap();
        for m in 0..3 {
            let exp_m = exp_mags[m].as_f64().unwrap();
            let diff = (star.abs_mags[m] - exp_m).abs();
            assert!(
                diff < 1e-4,
                "float-quantization {}: star mag[{}] diff {} exceeds tolerance (expected {}, got {})",
                name, m, diff, exp_m, star.abs_mags[m]
            );
        }
    }
}

#[test]
fn test_cpp_parity_padova_age_grid() {
    let data_dir = galaxia_rs::require_data_dir!();
    let db = IsochroneDB::load(&data_dir).expect("Load IsochroneDB");
    let state = IsochroneFieldState::new(&db);

    let fixtures = load_fixtures();
    let grid_cases = fixtures["padova_age_grid"]
        .as_array()
        .expect("padova_age_grid array");

    let mut max_mag_diff = 0.0_f64;
    let mut tested = 0;

    for c in grid_cases {
        let age = c["age"].as_f64().unwrap();
        let feh = c["feh"].as_f64().unwrap();
        let smass = c["smass"].as_f64().unwrap();
        let exp_acc = c["accepted"].as_bool().unwrap();

        let mut star = StarParticle::default();
        star.age = age;
        star.feh = feh;
        star.smass = smass;

        db.interpolate_star(&mut star, &state);
        let acc = star.abs_mags[0] < 1e5;
        assert_eq!(
            acc, exp_acc,
            "Age grid point age={} feh={} smass={}: accept mismatch",
            age, feh, smass
        );

        if acc {
            let exp_mags = c["mags"].as_array().unwrap();
            for m in 0..3 {
                let exp_m = exp_mags[m].as_f64().unwrap();
                let diff = (star.abs_mags[m] - exp_m).abs();
                if diff > max_mag_diff {
                    max_mag_diff = diff;
                }
                assert!(
                    diff < 1e-3,
                    "Age grid mag[{}] diff {} at age={} feh={} (expected {}, got {})",
                    m,
                    diff,
                    age,
                    feh,
                    exp_m,
                    star.abs_mags[m]
                );
            }
        }
        tested += 1;
    }

    assert!(
        tested >= 2000,
        "Expected at least 2000 age grid test cases, got {}",
        tested
    );
    println!(
        "Padova age grid parity passed ({} points, max mag diff: {:.2e})",
        tested, max_mag_diff
    );
}

