#[test]
fn test_cpp_parity_max_v_cache_hysteresis() {
    let data_dir = galaxia_rs::require_data_dir!();
    let db = IsochroneDB::load(&data_dir).expect("Load IsochroneDB");
    let mut state = IsochroneFieldState::new(&db);
    let mut imf = Sampler::for_pop_id(7);
    let mut rng = Philox::from_stream(1, 0, 7, 0, 0, 0);

    let fixtures = load_fixtures();
    let steps = fixtures["max_v_cache"]
        .as_array()
        .expect("max_v_cache array");

    let age_val = db.age_grid[100];
    let feh_val = db.feh_grid[15];

    for s in steps {
        let step_name = s["step_name"].as_str().unwrap();
        let max_v_in = s["max_v_input"].as_f64().unwrap();
        let track_idx = s["track_idx"].as_i64().unwrap() as usize;
        let exp_track_m_min = s["track_m_min"].as_f64().unwrap();
        let test_below_m = s["test_below_mass"].as_f64().unwrap();
        let exp_below_acc = s["below_accepted"].as_bool().unwrap();
        let test_above_m = s["test_above_mass"].as_f64().unwrap();
        let exp_above_acc = s["above_accepted"].as_bool().unwrap();

        // Update state with max_v_in
        db.set_isochrones1(
            &mut state, 11e9, 1e9, feh_val, 0.3, max_v_in, 1000.0, 0, &mut imf, &mut rng,
        );

        let actual_m_min = state.track_m_min[track_idx];
        assert!(
            (actual_m_min - exp_track_m_min).abs() < 1e-6,
            "Step {}: track_m_min mismatch (expected {}, got {})",
            step_name,
            exp_track_m_min,
            actual_m_min
        );

        // Test star below m_min
        let mut s_below = StarParticle::default();
        s_below.age = age_val;
        s_below.feh = feh_val;
        s_below.smass = test_below_m;
        db.interpolate_star(&mut s_below, &state);
        let below_acc = s_below.abs_mags[0] < 1e5;
        assert_eq!(
            below_acc, exp_below_acc,
            "Step {}: below mass {} accept mismatch",
            step_name, test_below_m
        );

        // Test star above m_min
        let mut s_above = StarParticle::default();
        s_above.age = age_val;
        s_above.feh = feh_val;
        s_above.smass = test_above_m;
        db.interpolate_star(&mut s_above, &state);
        let above_acc = s_above.abs_mags[0] < 1e5;
        assert_eq!(
            above_acc, exp_above_acc,
            "Step {}: above mass {} accept mismatch",
            step_name, test_above_m
        );
    }
}

#[test]
fn test_cpp_parity_leaf_order_and_reset() {
    let data_dir = galaxia_rs::require_data_dir!();
    let db = IsochroneDB::load(&data_dir).expect("Load IsochroneDB");
    let mut imf = Sampler::for_pop_id(7);
    let mut rng = Philox::from_stream(1, 0, 7, 0, 0, 0);

    let fixtures = load_fixtures();
    let steps = fixtures["leaf_order_and_reset"]
        .as_array()
        .expect("leaf_order_and_reset array");

    // Track active state per field
    let mut cur_field = 0;
    let mut state = IsochroneFieldState::new(&db);

    for s in steps {
        let field_id = s["field_id"].as_i64().unwrap() as usize;
        let leaf_idx = s["leaf_idx"].as_i64().unwrap() as usize;
        let max_v_in = s["max_v_input"].as_f64().unwrap();
        let track_idx = s["sample_track_idx"].as_i64().unwrap() as usize;
        let exp_track_m_min = s["sample_track_m_min"].as_f64().unwrap();
        let star_age = s["star_age"].as_f64().unwrap();
        let star_feh = s["star_feh"].as_f64().unwrap();
        let star_smass = s["star_smass"].as_f64().unwrap();
        let exp_acc = s["accepted"].as_bool().unwrap();

        if field_id != cur_field {
            cur_field = field_id;
            state = IsochroneFieldState::new(&db); // Clean reset matching C++ fresh DB instance
        }

        if leaf_idx > 0 || (field_id == 1 && leaf_idx == 0) {
            db.set_isochrones1(
                &mut state, 11e9, 1e9, star_feh, 0.3, max_v_in, 1000.0, 0, &mut imf, &mut rng,
            );
        }

        let actual_m_min = state.track_m_min[track_idx];
        assert!(
            (actual_m_min - exp_track_m_min).abs() < 1e-6,
            "Field {} Leaf {}: track_m_min mismatch (expected {}, got {})",
            field_id,
            leaf_idx,
            exp_track_m_min,
            actual_m_min
        );

        let mut star = StarParticle::default();
        star.age = star_age;
        star.feh = star_feh;
        star.smass = star_smass;
        db.interpolate_star(&mut star, &state);

        let acc = star.abs_mags[0] < 1e5;
        assert_eq!(
            acc, exp_acc,
            "Field {} Leaf {}: candidate star accept mismatch",
            field_id, leaf_idx
        );
    }
}

#[test]
fn test_cpp_parity_thindisk0_density_e0() {
    let _data_dir = galaxia_rs::require_data_dir!();
    let td0 = create_population(0, 1, 0); // pop 0, warp_flare=1, option_e=0

    let fixtures = load_fixtures();
    let cases = fixtures["thindisk0_density_e0"]
        .as_array()
        .expect("thindisk0_density_e0 array");

    let mut max_rel_diff = 0.0_f64;
    let mut tested = 0;

    for c in cases {
        let pos_arr = c["pos"].as_array().unwrap();
        let pos = [
            pos_arr[0].as_f64().unwrap(),
            pos_arr[1].as_f64().unwrap(),
            pos_arr[2].as_f64().unwrap(),
        ];
        let age = c["age"].as_f64().unwrap();
        let exp_density = c["density"].as_f64().unwrap();

        let rust_density = td0.density(&pos, age);

        let diff = (rust_density - exp_density).abs();
        let rel_diff = if exp_density > 0.0 {
            diff / exp_density
        } else {
            diff
        };
        if rel_diff > max_rel_diff {
            max_rel_diff = rel_diff;
        }

        assert!(
            rel_diff < 1e-10,
            "ThinDisk0 (E=0) density diff at pos={:?}, age={}: rel_diff {:.2e} (cpp={}, rust={})",
            pos,
            age,
            rel_diff,
            exp_density,
            rust_density
        );
        tested += 1;
    }

    assert!(
        tested >= 800,
        "Expected at least 800 density test cases, got {}",
        tested
    );
    println!(
        "ThinDisk0 (E=0) density parity passed ({} points, max rel diff: {:.2e})",
        tested, max_rel_diff
    );
}
